<?php

/**
 * The old names of moved classes resolve in tests and in static analysis.
 *
 * The map in appinfo/class-aliases.json keeps the old name of every class that moved to a
 * component directory working (ADR-012 Rule 4). Application::register() applies
 * it at boot; the test bootstraps and phpstan-bootstrap.php apply the same map,
 * and psalm reads it from tests/stubs/ClassAliases.php, generated by
 * scripts/class-alias-stubs.py. This test fails when that stub no longer
 * matches the json, and when an old name does not resolve under phpunit.
 *
 * SPDX-License-Identifier: EUPL-1.2
 * SPDX-FileCopyrightText: 2026 Conduction B.V.
 *
 * @category Test
 * @package  OCA\OpenRegister\Tests\Unit\Architecture
 *
 * @author    Conduction Development Team <info@conduction.nl>
 * @copyright 2026 Conduction B.V.
 * @license   EUPL-1.2 https://joinup.ec.europa.eu/collection/eupl/eupl-text-eupl-12
 *
 * @link https://www.OpenRegister.nl
 */

declare(strict_types=1);

namespace OCA\OpenRegister\Tests\Unit\Architecture;

use PHPUnit\Framework\TestCase;
use ReflectionClass;

class ClassAliasStubTest extends TestCase {

	/**
	 * The alias map.
	 *
	 * @var string
	 */
	private const MAP_FILE = __DIR__ . '/../../../appinfo/class-aliases.json';

	/**
	 * The generated psalm stub.
	 *
	 * @var string
	 */
	private const STUB_FILE = __DIR__ . '/../../stubs/ClassAliases.php';

	/**
	 * Old name => new name, from the json.
	 *
	 * @return array<string, string>
	 */
	private function aliases(): array {
		$data = json_decode((string) file_get_contents(self::MAP_FILE), true);
		$this->assertIsArray($data);
		$this->assertIsArray($data['aliases'] ?? null);

		$aliases = [];
		foreach ($data['aliases'] as $old => $entry) {
			$aliases[(string) $old] = (string) $entry['class'];
		}

		return $aliases;
	}//end aliases()

	/**
	 * Old name => new name, as the stub declares them.
	 *
	 * @return array<string, string>
	 */
	private function stubAliases(): array {
		$stub = (string) file_get_contents(self::STUB_FILE);

		$declared = [];
		preg_match_all("/class_alias\\('([A-Za-z0-9_\\\\]+)', '([A-Za-z0-9_\\\\]+)'\\);/", $stub, $calls, PREG_SET_ORDER);
		foreach ($calls as $call) {
			$declared[str_replace('\\\\', '\\', $call[2])] = str_replace('\\\\', '\\', $call[1]);
		}

		preg_match_all('/namespace ([A-Za-z0-9_\\\\]+) \\{\\n\\tinterface (\\w+) extends \\\\([A-Za-z0-9_\\\\]+) \\{/', $stub, $interfaces, PREG_SET_ORDER);
		foreach ($interfaces as $interface) {
			$declared[$interface[1].'\\'.$interface[2]] = $interface[3];
		}

		return $declared;
	}//end stubAliases()

	/**
	 * The psalm stub declares exactly the entries of the json.
	 *
	 * @return void
	 */
	public function testStubMatchesTheAliasMap(): void {
		$expected = $this->aliases();
		$actual   = $this->stubAliases();
		ksort($expected);
		ksort($actual);

		$this->assertSame(
			$expected,
			$actual,
			'tests/stubs/ClassAliases.php does not match appinfo/class-aliases.json: run python3 scripts/class-alias-stubs.py'
		);
	}//end testStubMatchesTheAliasMap()

	/**
	 * Every old name resolves to its new class under the phpunit bootstrap.
	 *
	 * @return void
	 */
	public function testEveryOldNameResolvesInTests(): void {
		$unresolved = [];
		foreach ($this->aliases() as $old => $new) {
			$exists = class_exists($old) || interface_exists($old) || enum_exists($old) || trait_exists($old);
			if ($exists === false || (new ReflectionClass($old))->getName() !== $new) {
				$unresolved[] = $old.' -> '.$new;
			}
		}

		$this->assertSame(
			[],
			$unresolved,
			'Old class names the test bootstrap does not resolve (is ClassAliasMap::aliasClasses() still called in tests/bootstrap*.php?)'
		);
	}//end testEveryOldNameResolvesInTests()
}//end class
